INSERT INTO coding_problems
(id, title, description, difficulty, tags, input_format, output_format, constraints, created_by, created_at)
VALUES
(1, E'Array Sum', E'Given n integers, print their sum.', E'easy', ARRAY['arrays','math'], E'First line n. Second line n integers.', E'Print the sum.', E'1 ≤ n ≤ 100000; values fit in signed 64-bit.', NULL, CURRENT_TIMESTAMP),
(2, E'Maximum Element', E'Print the largest element in an integer array.', E'easy', ARRAY['arrays'], E'First line n. Second line n integers.', E'Print the maximum.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(3, E'Reverse a String', E'Reverse the given string exactly as provided.', E'easy', ARRAY['strings'], E'One line containing a non-empty string without spaces.', E'Print the reversed string.', E'1 ≤ length ≤ 100000; input contains printable ASCII characters except spaces.', NULL, CURRENT_TIMESTAMP),
(4, E'Palindrome Check', E'Determine whether a string reads the same forward and backward.', E'easy', ARRAY['strings'], E'One line containing a non-empty lowercase string.', E'Print YES if palindrome, otherwise NO.', E'1 ≤ length ≤ 100000; lowercase English letters only.', NULL, CURRENT_TIMESTAMP),
(5, E'Count Vowels', E'Count the lowercase vowels a, e, i, o, u in a string.', E'easy', ARRAY['strings'], E'One line containing a lowercase string.', E'Print the vowel count.', E'1 ≤ length ≤ 100000; lowercase English letters only.', NULL, CURRENT_TIMESTAMP),
(6, E'Character Frequency', E'Print the frequency of each lowercase letter that occurs, in alphabetical order.', E'easy', ARRAY['hash-map','strings'], E'One line containing a lowercase string.', E'For each occurring character print ''character frequency'' separated by spaces.', E'1 ≤ length ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(7, E'Linear Search', E'Find the first zero-based index of target in an array, or -1.', E'easy', ARRAY['searching','arrays'], E'First line n. Second line n integers. Third line target.', E'Print the first index or -1.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(8, E'Second Largest Distinct', E'Print the second largest distinct array value; print -1 if fewer than two distinct values.', E'easy', ARRAY['arrays','sorting'], E'First line n. Second line n integers.', E'Print the second largest distinct value, or -1.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(9, E'Sort Integers', E'Sort n integers in nondecreasing order.', E'easy', ARRAY['sorting','arrays'], E'First line n. Second line n integers.', E'Print the sorted integers separated by spaces.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(10, E'Remove Adjacent Duplicates', E'Given a sorted array, print each distinct value once.', E'easy', ARRAY['arrays','two-pointers'], E'First line n. Second line n sorted integers.', E'Print distinct values separated by spaces.', E'1 ≤ n ≤ 100000; array is nondecreasing.', NULL, CURRENT_TIMESTAMP),
(11, E'Balanced Brackets', E'Check whether brackets (), [], and {} are properly nested.', E'easy', ARRAY['stack','strings'], E'One line containing a bracket string.', E'Print YES if balanced, otherwise NO.', E'1 ≤ length ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(12, E'Queue Operations', E'Process ENQUEUE x and DEQUEUE operations. DEQUEUE prints and removes the front value, or -1 if empty.', E'easy', ARRAY['queue'], E'First line q. Next q lines contain an operation: ENQUEUE x or DEQUEUE.', E'Print all DEQUEUE results separated by spaces.', E'1 ≤ q ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(13, E'Word Count', E'Count the number of whitespace-separated words in a line.', E'easy', ARRAY['strings'], E'One line containing text.', E'Print the number of words.', E'1 ≤ line length ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(14, E'Greatest Common Divisor', E'Compute gcd(a,b), the greatest positive integer dividing both.', E'easy', ARRAY['math'], E'One line: a b.', E'Print gcd(a,b).', E'1 ≤ a,b ≤ 10^18.', NULL, CURRENT_TIMESTAMP),
(15, E'Digit Sum', E'Print the sum of decimal digits of a non-negative integer.', E'easy', ARRAY['math'], E'One line containing n.', E'Print the digit sum.', E'0 ≤ n ≤ 10^18.', NULL, CURRENT_TIMESTAMP),
(16, E'Merge Two Sorted Arrays', E'Merge two nondecreasing arrays into one nondecreasing sequence.', E'easy', ARRAY['arrays','two-pointers','sorting'], E'Line 1: n. Line 2: n integers. Line 3: m. Line 4: m integers.', E'Print the merged sequence.', E'1 ≤ n,m ≤ 100000; arrays are sorted.', NULL, CURRENT_TIMESTAMP),
(17, E'Factorial', E'Compute n! exactly for small n.', E'easy', ARRAY['math','recursion'], E'One line n.', E'Print n!.', E'0 ≤ n ≤ 20.', NULL, CURRENT_TIMESTAMP),
(18, E'Integer Power', E'Compute a^b for nonnegative integer b.', E'easy', ARRAY['math','recursion'], E'One line: a b.', E'Print a^b.', E'0 ≤ a ≤ 10; 0 ≤ b ≤ 18.', NULL, CURRENT_TIMESTAMP),
(19, E'Even or Odd Count', E'Count how many numbers in an array are even.', E'easy', ARRAY['arrays','math'], E'First line n. Second line n integers.', E'Print the number of even elements.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(20, E'Rotate Array Right by One', E'Move the last element of the array to the first position.', E'easy', ARRAY['arrays'], E'First line n. Second line n integers.', E'Print the rotated array.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(21, E'Two Sum', E'Print indices of the first pair of distinct elements whose values sum to target, using the smallest second index found by a left-to-right scan; print -1 -1 if none.', E'medium', ARRAY['arrays','hash-map'], E'First line n. Second line n integers. Third line target.', E'Print two zero-based indices i j with i < j, or -1 -1.', E'2 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(22, E'Maximum Subarray Sum', E'Find the maximum sum of any non-empty contiguous subarray.', E'medium', ARRAY['arrays','dynamic-programming'], E'First line n. Second line n integers.', E'Print the maximum subarray sum.', E'1 ≤ n ≤ 100000; values fit 32-bit signed integers.', NULL, CURRENT_TIMESTAMP),
(23, E'Longest Substring Without Repeating Characters', E'Print the length of the longest substring containing no repeated characters.', E'medium', ARRAY['strings','sliding-window','hash-map'], E'One line containing a string.', E'Print the maximum length.', E'0 ≤ length ≤ 100000; lowercase English letters.', NULL, CURRENT_TIMESTAMP),
(24, E'Anagram Check', E'Determine whether two strings contain exactly the same multiset of characters.', E'medium', ARRAY['strings','hash-map','sorting'], E'Line 1 string s. Line 2 string t.', E'Print YES or NO.', E'0 ≤ lengths ≤ 100000; lowercase letters.', NULL, CURRENT_TIMESTAMP),
(25, E'Binary Search', E'Find the zero-based index of target in a sorted array, or -1.', E'medium', ARRAY['binary-search','searching'], E'First line n. Second line n sorted integers. Third line target.', E'Print an index or -1.', E'1 ≤ n ≤ 100000; array is strictly increasing.', NULL, CURRENT_TIMESTAMP),
(26, E'Maximum Sum Window', E'Find the maximum sum of any contiguous subarray of exactly k elements.', E'medium', ARRAY['sliding-window','arrays'], E'First line n. Second line n integers. Third line k.', E'Print the maximum window sum.', E'1 ≤ k ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(27, E'Next Greater Element', E'For each array element, print the first greater element to its right, or -1.', E'medium', ARRAY['stack','arrays'], E'First line n. Second line n integers.', E'Print n answers separated by spaces.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(28, E'Middle of Linked List', E'Given node values in linked-list order, print the value at the middle. For even length, print the first of the two middle values.', E'medium', ARRAY['linked-list'], E'First line n. Second line n node values.', E'Print the middle value.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(29, E'Reverse Word Order', E'Reverse the order of whitespace-separated words in a sentence.', E'medium', ARRAY['strings'], E'One line containing a sentence.', E'Print the words in reverse order separated by one space.', E'1 ≤ line length ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(30, E'Range Sum Queries', E'Answer each inclusive range-sum query on an integer array.', E'medium', ARRAY['arrays','prefix-sum'], E'Line 1 n. Line 2 n integers. Line 3 q. Next q lines: l r (zero-based, inclusive).', E'Print one sum per query.', E'1 ≤ n,q ≤ 100000; 0 ≤ l ≤ r < n.', NULL, CURRENT_TIMESTAMP),
(31, E'Merge Overlapping Intervals', E'Merge all overlapping closed integer intervals.', E'medium', ARRAY['sorting','arrays'], E'First line n. Next n lines contain l r.', E'Print merged intervals, one per line, sorted by start.', E'1 ≤ n ≤ 100000; l ≤ r.', NULL, CURRENT_TIMESTAMP),
(32, E'Breadth-First Traversal', E'Perform BFS on an undirected graph from a given start vertex. Visit neighbors in increasing vertex order.', E'medium', ARRAY['graphs','queue'], E'First line n m. Next m lines edges u v. Last line start.', E'Print visited vertices in BFS order.', E'1 ≤ n ≤ 10000; 0 ≤ m ≤ 20000; vertices are 0..n-1.', NULL, CURRENT_TIMESTAMP),
(33, E'Connected Components', E'Count connected components in an undirected graph.', E'medium', ARRAY['graphs'], E'First line n m. Next m lines edges u v.', E'Print the number of connected components.', E'1 ≤ n ≤ 10000; 0 ≤ m ≤ 20000.', NULL, CURRENT_TIMESTAMP),
(34, E'Climbing Stairs', E'There are n steps. Each move climbs either 1 or 2 steps. Count distinct ways to reach exactly step n.', E'medium', ARRAY['dynamic-programming','recursion'], E'One line n.', E'Print the number of ways.', E'0 ≤ n ≤ 40.', NULL, CURRENT_TIMESTAMP),
(35, E'Minimum Coin Count', E'Given coin denominations with unlimited supply, find the minimum number of coins needed to form amount, or -1 if impossible.', E'medium', ARRAY['dynamic-programming','greedy'], E'First line n. Second line n coin values. Third line amount.', E'Print minimum coin count or -1.', E'1 ≤ n ≤ 20; 1 ≤ coin ≤ 1000; 0 ≤ amount ≤ 10000.', NULL, CURRENT_TIMESTAMP),
(36, E'Maximum Non-Overlapping Activities', E'Select the maximum number of activities where an activity can start at or after the previous selected activity ends.', E'medium', ARRAY['greedy','sorting'], E'First line n. Next n lines start end.', E'Print the maximum number of selected activities.', E'1 ≤ n ≤ 100000; start ≤ end.', NULL, CURRENT_TIMESTAMP),
(37, E'Unique Characters', E'Determine whether all characters in the string are distinct.', E'medium', ARRAY['hash-map','strings'], E'One line string.', E'Print YES or NO.', E'0 ≤ length ≤ 100000; lowercase letters.', NULL, CURRENT_TIMESTAMP),
(38, E'Product Except Self', E'For each position, print the product of all array values except the value at that position.', E'medium', ARRAY['arrays'], E'First line n. Second line n integers.', E'Print n products separated by spaces.', E'2 ≤ n ≤ 100000; intermediate products fit signed 64-bit.', NULL, CURRENT_TIMESTAMP),
(39, E'Longest Consecutive Sequence', E'Print the length of the longest sequence of consecutive integer values.', E'medium', ARRAY['hash-map','arrays'], E'First line n. Second line n integers.', E'Print the maximum length.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(40, E'Complete Binary Tree Height', E'A complete binary tree has n nodes. Compute its height in edges; a one-node tree has height 0.', E'medium', ARRAY['trees','math'], E'One line n.', E'Print the height in edges.', E'1 ≤ n ≤ 1000000000.', NULL, CURRENT_TIMESTAMP),
(41, E'Edit Distance', E'Compute the minimum number of insertions, deletions, and substitutions needed to transform one string into another.', E'hard', ARRAY['dynamic-programming','strings'], E'Line 1 string s. Line 2 string t.', E'Print the edit distance.', E'0 ≤ lengths ≤ 1000; lowercase letters.', NULL, CURRENT_TIMESTAMP),
(42, E'0/1 Knapsack', E'Choose each item at most once to maximize total value without exceeding capacity.', E'hard', ARRAY['dynamic-programming'], E'Line 1: n capacity. Line 2: n weights. Line 3: n values.', E'Print maximum value.', E'1 ≤ n ≤ 100; 1 ≤ capacity ≤ 10000; weights and values are positive.', NULL, CURRENT_TIMESTAMP),
(43, E'Shortest Paths', E'Find shortest distances from source to every vertex in an undirected weighted graph.', E'hard', ARRAY['graphs','greedy'], E'First line n m. Next m lines u v w. Last line source.', E'Print n distances in vertex order; print -1 for unreachable vertices.', E'1 ≤ n ≤ 10000; 0 ≤ m ≤ 20000; weights are positive integers.', NULL, CURRENT_TIMESTAMP),
(44, E'Longest Increasing Subsequence', E'Print the length of a strictly increasing subsequence of maximum length.', E'hard', ARRAY['dynamic-programming','binary-search'], E'First line n. Second line n integers.', E'Print the LIS length.', E'1 ≤ n ≤ 100000.', NULL, CURRENT_TIMESTAMP),
(45, E'Minimum Grid Path', E'Starting at the top-left cell, move only right or down to reach the bottom-right cell with minimum sum of visited cell values.', E'hard', ARRAY['dynamic-programming','arrays'], E'First line r c. Next r lines contain c nonnegative integers.', E'Print the minimum path sum.', E'1 ≤ r,c ≤ 100; cell values ≤ 1000.', NULL, CURRENT_TIMESTAMP),
(46, E'Directed Graph Cycle Check', E'Determine whether a directed graph contains a cycle.', E'hard', ARRAY['graphs','queue','greedy'], E'First line n m. Next m lines directed edges u v.', E'Print YES if the graph contains a cycle, otherwise NO.', E'1 ≤ n ≤ 10000; 0 ≤ m ≤ 30000.', NULL, CURRENT_TIMESTAMP),
(47, E'Matrix Chain Multiplication', E'Given dimensions of a chain of matrices, find the minimum scalar multiplications needed to multiply them all.', E'hard', ARRAY['dynamic-programming'], E'Line 1 n, the number of matrices. Line 2 contains n+1 dimensions.', E'Print the minimum multiplication count.', E'1 ≤ n ≤ 100; dimensions ≤ 1000.', NULL, CURRENT_TIMESTAMP),
(48, E'Lexicographically Smallest Topological Order', E'For a directed acyclic graph, output a topological ordering that is lexicographically smallest. If a cycle exists, print -1.', E'hard', ARRAY['graphs','greedy','queue'], E'First line n m. Next m lines directed edges u v.', E'Print the ordering or -1.', E'1 ≤ n ≤ 10000; 0 ≤ m ≤ 30000.', NULL, CURRENT_TIMESTAMP),
(49, E'Subset Sum', E'Determine whether some subset of the given nonnegative integers sums exactly to target.', E'hard', ARRAY['dynamic-programming'], E'First line n. Second line n nonnegative integers. Third line target.', E'Print YES or NO.', E'1 ≤ n ≤ 100; each value ≤ 1000; target ≤ 10000.', NULL, CURRENT_TIMESTAMP),
(50, E'Minimum Jumps to End', E'Each array value gives the maximum forward jump length from that index. Find the minimum jumps from index 0 to the last index, or -1 if unreachable.', E'hard', ARRAY['arrays','greedy'], E'First line n. Second line n nonnegative integers.', E'Print minimum jumps or -1.', E'1 ≤ n ≤ 100000; 0 ≤ a[i] ≤ 100000.', NULL, CURRENT_TIMESTAMP);
